}

void loop() {
  if (digitalRead(START_PIN) == LOW) {
    motorOn = true;
  }
  if (digitalRead(STOP_PIN) == LOW) {
    motorOn = false;   // stop is written last so it wins
  }
  digitalWrite(MOTOR_PIN, motorOn);
}

