#include <P1AM.h>

bool motorOn = false;

void setup() {
  while (!P1.init()) {
    ; // wait for modules
  }
}

void loop() {
  bool startPB = P1.readDiscrete(1, 1);
  bool stopOk = P1.readDiscrete(1, 2);   // NC stop: true when not pressed
  if (!stopOk) {
    motorOn = false;
  } else if (startPB) {
    motorOn = true;
  }
  P1.writeDiscrete(motorOn, 2, 1);
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int MOTOR_PIN = 8;
enum State { IDLE, RUNNING };
State state = IDLE;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  switch (state) {
    case IDLE:
      digitalWrite(MOTOR_PIN, LOW);
      if (startPressed && !stopPressed) {
        state = RUNNING;
      }
      break;
    case RUNNING:
      digitalWrite(MOTOR_PIN, HIGH);
      if (stopPressed) {
        state = IDLE;
      }
      break;
  }
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int ESTOP_PIN = 4;
const int CONVEYOR_PIN = 8;
const int LAMP_PIN = 9;
bool conveyorRunning = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(ESTOP_PIN, INPUT_PULLUP);
  pinMode(CONVEYOR_PIN, OUTPUT);
  pinMode(LAMP_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  bool estopPressed = digitalRead(ESTOP_PIN) == HIGH; // NC e-stop opens

  if (estopPressed || stopPressed) {
    conveyorRunning = false;
    digitalWrite(LAMP_PIN, LOW);
  } else if (startPressed) {
    conveyorRunning = true;
    digitalWrite(LAMP_PIN, HIGH);
  }
  digitalWrite(CONVEYOR_PIN, conveyorRunning ? HIGH : LOW);
}

const int START_PIN = 2;
const int STOP_PIN = 3;
const int OVERLOAD_PIN = 4;
const int PUMP_PIN = 7;
int pumpState = LOW;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(OVERLOAD_PIN, INPUT);
  pinMode(PUMP_PIN, OUTPUT);
}

void loop() {
  if (digitalRead(OVERLOAD_PIN) == HIGH || digitalRead(STOP_PIN) == LOW) {
    pumpState = LOW;
  } else if (digitalRead(START_PIN) == LOW) {
    pumpState = HIGH;
  }
  digitalWrite(PUMP_PIN, pumpState);
}

const int LEFT_PIN = 2;
const int RIGHT_PIN = 3;
const int STOP_PIN = 4;
const int PRESS_PIN = 8;
bool pressRun = false;
unsigned long firstPress = 0;
bool waiting = false;

void setup() {
  pinMode(LEFT_PIN, INPUT_PULLUP);
  pinMode(RIGHT_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(PRESS_PIN, OUTPUT);
}

void loop() {
  bool left = digitalRead(LEFT_PIN) == LOW;
  bool right = digitalRead(RIGHT_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;

  if ((left || right) && !waiting) {
    waiting = true;
    firstPress = millis();
  }
  if (!left && !right) {
    waiting = false;
  }

  if (stopPressed) {
    pressRun = false;
  } else if (left && right && (millis() - firstPress < 500)) {
    pressRun = true;
  } else if (!left || !right) {
    pressRun = false;  // two-hand: release either hand drops the press
  }
  digitalWrite(PRESS_PIN, pressRun);
}

