const int REV_PIN = 5;
const int FWD_OUT = 9;
const int REV_OUT = 10;
bool fwd = false;
bool rev = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool fwdPressed = digitalRead(FWD_PIN) == LOW;
  bool revPressed = digitalRead(REV_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  if (stopPressed) {
    fwd = false;
    rev = false;
  } else if (fwdPressed && !rev) {
    fwd = true;
  } else if (revPressed && !fwd) {
    rev = true;
  }
  digitalWrite(FWD_OUT, fwd);
  digitalWrite(REV_OUT, rev);
}

