const int START_PIN = 2, STOP_PIN = 3, OL_PIN = 4, PUMP_PIN = 7;
bool pumpOn = false;
bool faultLatched = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(OL_PIN, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;
  bool overloadTripped = digitalRead(OL_PIN) == HIGH;

  // pressing start clears an old overload fault
  if (startPressed) {
    faultLatched = false;
  } else if (overloadTripped) {
    faultLatched = true;
  }

  if (stopPressed || overloadTripped || faultLatched) {
    pumpOn = false;
  } else if (startPressed) {
    pumpOn = true;
  }
  digitalWrite(PUMP_PIN, pumpOn);
}

// Motor start/stop with debounce
const byte START_PIN = 2;
const byte STOP_PIN = 3;
const byte MOTOR_PIN = 8;
const unsigned long DEBOUNCE_MS = 30;

bool motorRunning = false;
bool lastStart = HIGH, lastStop = HIGH;
unsigned long tStart = 0, tStop = 0;
bool startState = HIGH, stopState = HIGH;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
  Serial.begin(115200);
  Serial.println(F("Motor controller ready"));
}

bool debounce(byte pin, bool &last, unsigned long &t, bool &state) {
  bool r = digitalRead(pin);
  if (r != last) t = millis();
  if (millis() - t > DEBOUNCE_MS) state = r;
  last = r;
  return state == LOW;
}

void loop() {
  bool startPressed = debounce(START_PIN, lastStart, tStart, startState);
  bool stopPressed  = debounce(STOP_PIN, lastStop, tStop, stopState);

  // STOP always wins over START (fail-safe)
  if (stopPressed) {
    if (motorRunning) Serial.println(F("STOP"));
    motorRunning = false;
  } else if (startPressed) {
    if (!motorRunning) Serial.println(F("START"));
    motorRunning = true;
  }

  digitalWrite(MOTOR_PIN, motorRunning ? HIGH : LOW);
}

