  digitalWrite(MOTOR_PIN, running);
}

enum ConvState { STOPPED, RUNNING };
ConvState state = STOPPED;

void loop() {
  bool startPressed = digitalRead(2) == LOW;
  bool stopPressed = digitalRead(3) == LOW;
  bool estop = digitalRead(4) == HIGH;

  if (estop || stopPressed) state = STOPPED;

  switch (state) {
    case STOPPED:
      digitalWrite(8, LOW);
      if (startPressed && !estop && !stopPressed) state = RUNNING;
      break;
    case RUNNING:
      digitalWrite(8, HIGH);
      break;
  }
}

