    case IDLE:
      if (startPressed) state = RUNNING;
      break;
    case RUNNING:
      if (startPressed) {
        state = RUNNING;
      } else if (stopPressed) {
        state = IDLE;
      }
      break;
  }
  digitalWrite(MOTOR_PIN, state == RUNNING ? HIGH : LOW);
}

