PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Stop THEN
    Motor := FALSE;
ELSIF Start THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    StartPB : BOOL;
    StopPB_NC : BOOL;  (* TRUE when healthy *)
    EStop : BOOL;
    Conveyor : BOOL;
END_VAR

Conveyor := (StartPB OR Conveyor) AND StopPB_NC AND NOT EStop;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Start THEN
    Motor := TRUE;
END_IF;
IF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    MotorLatch : RS;
END_VAR

MotorLatch(SET := Start, RESET1 := Stop);
Motor := MotorLatch.Q1;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    State : INT := 0;
END_VAR

CASE State OF
    0: (* stopped *)
        Motor := FALSE;
        IF Start AND NOT Stop THEN
            State := 1;
        END_IF;
    1: (* running *)
        Motor := TRUE;
        IF Stop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    StartDelay : TON;
END_VAR

StartDelay(IN := Start AND NOT Stop, PT := T#3S);
IF Stop THEN
    Motor := FALSE;
ELSIF StartDelay.Q THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Start AND NOT Stop THEN
    Motor := TRUE;
ELSIF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    StartFwd : BOOL;
    StartRev : BOOL;
    Stop : BOOL;
    Fwd : BOOL;
    Rev : BOOL;
END_VAR

IF Stop THEN
    Fwd := FALSE;
    Rev := FALSE;
ELSIF StartFwd AND NOT Rev THEN
    Fwd := TRUE;
ELSIF StartRev AND NOT Fwd THEN
    Rev := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Overload : BOOL;
    Pump : BOOL;
END_VAR

Pump := (Start OR Pump) AND NOT Stop AND NOT Overload;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    RunTimer : TON;
