RunTimer(IN := Motor, PT := T#30S);
IF Start THEN
    Motor := TRUE;
ELSIF RunTimer.Q THEN
    Motor := FALSE;
END_IF;
IF Stop THEN
    Motor := FALSE;
END_IF;

END_PROGRAM

