END_PROGRAM

PROGRAM PLC_PRG
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Conveyor : BOOL;
    Step : INT;
END_VAR

IF EStop OR StopPB THEN
    Step := 0;
END_IF;

CASE Step OF
    0:
        Conveyor := FALSE;
        IF StartPB AND NOT StopPB AND NOT EStop THEN
            Step := 10;
