#include <LiquidCrystal.h>
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);
const int LEFT_PREV_PIN = 6;
const int AT_STOP_PIN = 7;
bool countdownActive = false;
unsigned long leftAt = 0;

void setup() {
  lcd.begin(16, 2);
  pinMode(LEFT_PREV_PIN, INPUT_PULLUP);
  pinMode(AT_STOP_PIN, INPUT_PULLUP);
}

void loop() {
  bool busLeftPrevStop = digitalRead(LEFT_PREV_PIN) == LOW;
