PROGRAM TrafficLight
VAR
    Phase : INT := 0;
    PhaseTimer : TON;
    PedButton : BOOL;
    PedRequest : BOOL;
    StopPhaseDone : BOOL;
    Red, Yellow, Green, Walk : BOOL;
END_VAR

IF PedButton THEN
    PedRequest := TRUE;
ELSIF StopPhaseDone THEN
    PedRequest := FALSE;
END_IF;

CASE Phase OF
    0: Green := TRUE; Yellow := FALSE; Red := FALSE; Walk := FALSE;
       PhaseTimer(IN := TRUE, PT := T#20S);
       IF PhaseTimer.Q THEN PhaseTimer(IN := FALSE); Phase := 1; END_IF;
    1: Green := FALSE; Yellow := TRUE;
       PhaseTimer(IN := TRUE, PT := T#3S);
       IF PhaseTimer.Q THEN PhaseTimer(IN := FALSE); Phase := 2; END_IF;
    2: Yellow := FALSE; Red := TRUE; Walk := PedRequest;
       PhaseTimer(IN := TRUE, PT := T#15S);
       StopPhaseDone := PhaseTimer.Q;
       IF PhaseTimer.Q THEN PhaseTimer(IN := FALSE); Phase := 0; END_IF;
END_CASE;

END_PROGRAM

const int TRIG = 9, ECHO = 10;
const int MOTOR_L = 5, MOTOR_R = 6;
const int STOP_DISTANCE = 20;
const int CLEAR_DISTANCE = 30;
bool driving = false;

long readCm() {
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  return pulseIn(ECHO, HIGH, 30000) / 58;
}

void setup() {
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
  pinMode(MOTOR_L, OUTPUT); pinMode(MOTOR_R, OUTPUT);
}

void loop() {
  long distance = readCm();
  if (distance > CLEAR_DISTANCE) {
    driving = true;
  } else if (distance < STOP_DISTANCE) {
    driving = false;
  }
  analogWrite(MOTOR_L, driving ? 180 : 0);
  analogWrite(MOTOR_R, driving ? 180 : 0);
}

