PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Stop THEN
    Motor := FALSE;
ELSIF Start THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Stop THEN
    Motor := FALSE;
END_IF;
IF Start AND NOT Stop THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Conveyor : BOOL;
    RunLamp : BOOL;
    FaultLamp : BOOL;
    IdleCount : INT;
END_VAR

IF EStop THEN
    Conveyor := FALSE;
    FaultLamp := TRUE;
ELSIF StopPB THEN
    Conveyor := FALSE;
    RunLamp := FALSE;
ELSIF StartPB THEN
    Conveyor := TRUE;
    RunLamp := TRUE;
ELSE
    IdleCount := IdleCount + 1;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    StartPB, StopPB, EStop, Run : BOOL;
END_VAR

IF StopPB OR EStop THEN
    Run := FALSE;
ELSIF StartPB THEN
    Run := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    StopOK : BOOL;  (* NC *)
    Motor : BOOL;
END_VAR

Motor := (Start OR Motor) AND StopOK;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

IF Stop THEN
    Motor := FALSE;
ELSIF Start OR Motor THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start, Stop, Overload, Pump : BOOL;
END_VAR

IF Stop OR Overload THEN
    Pump := FALSE;
ELSIF Start THEN
    Pump := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    Mode : INT := 1;
END_VAR

CASE Mode OF
    1: (* auto *)
        IF Stop THEN
            Motor := FALSE;
        ELSIF Start THEN
            Motor := TRUE;
        END_IF;
    2: (* manual *)
        Motor := FALSE;
END_CASE;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    StartDelay : TON;
END_VAR

StartDelay(IN := Start, PT := T#2S);
IF Stop THEN
    Motor := FALSE;
ELSIF StartDelay.Q THEN
    Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    StopOK : BOOL;
    Motor : BOOL;
