PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

Motor := (Start OR Motor) AND NOT Stop;

END_PROGRAM

program main
var
    start, stop, motor : bool;
end_var
if stop then
    motor := false;
elsif start then
    motor := true;
end_if;
end_program

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
    RunLamp : BOOL;
    Starts : INT;
END_VAR

IF Stop THEN
    Motor := FALSE;
    RunLamp := FALSE;
END_IF;
IF Start AND NOT Stop THEN
    Motor := TRUE;
    RunLamp := TRUE;
    Starts := Starts + 1;
END_IF;

END_PROGRAM

PROGRAM PLC_PRG
VAR
    Start : BOOL;
    Stop : BOOL;
    Motor : BOOL;
END_VAR

